```

List directory contents with filtering and depth control.

exec tool declaration:
```ts
declare const tools: { mcp__basic_memory__list_directory(args: {
  // Recursion depth (1-10, default: 1 for immediate children only)
  // Higher values show subdirectory contents recursively
  depth?: number;
  // Directory path to list (default: root "/")
  // Examples: "/", "/projects", "/research/ml"
  dir_name?: string;
  // Optional glob pattern for filtering file names
  // Examples: "*.md", "*meeting*", "project_*"
  file_name_glob?: string | null;
  // Project name to list directory from. Optional - server will resolve using hierarchy.
  // If unknown, use list_memory_projects() to discover available projects.
  project?: string | null;
  // Project external_id (UUID). Prefer this over `project` when known —
  // it routes to the exact project regardless of name collisions across cloud
  // workspaces. Takes precedence over `project`. Get from list_memory_projects().
  project_id?: string | null;
}): Promise<CallToolResult<{ result: string; }>>; };
